#!/usr/bin/env python3
"""Measure the boot timeline after a software reboot.

Sends "reboot" to the CP shell and timestamps every chunk that comes back.
The gap between the reset taking effect and the first firmware output is the
window in which the bootrom is listening for a download handshake -- that is
the window an automated flash has to hit.
"""

import os
import sys
import time

PORT = "/dev/ttyUSB0"


def main():
    fd = os.open(PORT, os.O_RDWR | os.O_NOCTTY | os.O_NONBLOCK)
    try:
        # Drain anything stale.
        deadline = time.time() + 0.4
        while time.time() < deadline:
            try:
                os.read(fd, 4096)
            except BlockingIOError:
                time.sleep(0.02)
            except OSError:
                break

        print("发送 reboot ...")
        t0 = time.time()
        os.write(fd, b"reboot\r\n")

        events = []
        end = t0 + 6.0
        while time.time() < end:
            try:
                chunk = os.read(fd, 4096)
                if chunk:
                    events.append((time.time() - t0, chunk))
            except BlockingIOError:
                time.sleep(0.005)
            except OSError:
                break

        print("\n=== 时间线（相对发出 reboot 的时刻）===")
        if not events:
            print("  (整段 6 秒没有任何输出 —— reboot 可能没生效)")
            return

        for dt, chunk in events:
            text = chunk.decode("utf-8", "replace")
            first = next((l.strip() for l in text.splitlines() if l.strip()),
                         "")
            if len(first) > 70:
                first = first[:70] + "..."
            print("  %6.3f s  %4d 字节  %s" % (dt, len(chunk), first))

        print("\n=== 关键间隔 ===")
        print("  首个字节出现在  %.3f s" % events[0][0])
        gaps = []
        for i in range(1, len(events)):
            gap = events[i][0] - events[i - 1][0]
            if gap > 0.15:
                gaps.append((events[i - 1][0], events[i][0], gap))
        if gaps:
            print("  输出中的静默间隙（>150ms，bootrom 窗口候选）:")
            for a, b, g in gaps[:8]:
                print("      %.3f s → %.3f s   静默 %.3f s" % (a, b, g))
        else:
            print("  没有明显静默间隙")
    finally:
        os.close(fd)


if __name__ == "__main__":
    sys.exit(main())

