  /* Encoder thread and its wakeup.  The semaphore is posted by the framework
   * callbacks (which run on the caller's thread) and waited on here, so no
   * encoding ever happens on a caller's stack.
   */

  pthread_t             thread;
  sem_t                 wake;
  bool                  thread_running;
  bool                  stop;
""",
