  if (enc->scratch != NULL)""",
    """static int bk7258_jpeg_close(void *priv)
{
  struct bk7258_jpeg_enc_s *enc = priv;

  /* Stop the thread before releasing anything it touches. */

  if (enc->thread_running)
    {
      enc->stop = true;
      sem_post(&enc->wake);
      pthread_join(enc->thread, NULL);
