#!/usr/bin/env python3
"""Free each pool with the allocator that produced it, decided by address.

Hand-rolled slot tracking was leaking about 57 KB per session: the lookup
missed, so every pool fell through to the PSRAM fallback.  For PSRAM pools
that happened to be right, which is why only main-heap pools leaked and the
PSRAM heap always looked clean.

bk7258_psram_contains() already answers the question without any state to keep
in sync, so use it and stop guessing.  Pool extents are still recorded, but
only for the bounds check on incoming buffers.
"""

import sys

P = ("/home/mi/vela_competition_ap_console_dev/contest/"
     "contest2026_264_VelaSightsuixingAIzhinengyanjing/board/beken/boards/"
     "bk7258/bk7258-ap/src/bk7258_jpeg_enc.c")

src = open(P).read()
edits = []


def sub(old, new, label):
    global src
    n = src.count(old)
    if n != 1:
        print("FAIL [%s]: found %d, expected 1" % (label, n))
        sys.exit(1)
    src = src.replace(old, new, 1)
    edits.append(label)


# pool_psram[] no longer decides anything.
sub("""  void                 *pool[2];
  size_t                pool_size[2];
  bool                  pool_psram[2];""",
    """  void                 *pool[2];
  size_t                pool_size[2];""",
    "drop pool_psram")

sub("""          enc->pool[slot] = addr;
          enc->pool_size[slot] = size;
          enc->pool_psram[slot] = use_psram;
          break;""",
    """          enc->pool[slot] = addr;
          enc->pool_size[slot] = size;
          break;""",
    "drop psram flag record")

sub("""static void bk7258_jpeg_free_buf(void *priv, void *addr)
{
  struct bk7258_jpeg_enc_s *enc = priv;
  int slot;

  if (addr == NULL)
    {
      return;
    }

  for (slot = 0; slot < 2; slot++)
    {
      if (enc->pool[slot] == addr)
        {
          if (enc->pool_psram[slot])
            {
              bk7258_psram_free(addr);
            }
          else
            {
              kumm_free(addr);
            }

          enc->pool[slot] = NULL;
          enc->pool_size[slot] = 0;
          return;
        }
    }

  /* Unknown pointer: it can only have come from PSRAM, since that is the
   * fallback path, and leaking it would be worse than a wrong free here.
   */

  bk7258_psram_free(addr);
}""",
    """static void bk7258_jpeg_free_buf(void *priv, void *addr)
{
  struct bk7258_jpeg_enc_s *enc = priv;
  int slot;

  if (addr == NULL)
    {
      return;
    }

  /* Which allocator owns this is a property of the address, so ask rather
   * than remember.  Bookkeeping that can drift out of step is how this
   * leaked in the first place.
   */

  if (bk7258_psram_contains(addr, 1))
    {
      bk7258_psram_free(addr);
    }
  else
    {
      kumm_free(addr);
    }

  /* Drop it from the bounds-check table too, so a stale extent cannot make a
   * freed pool look like a valid encode target.
   */

  for (slot = 0; slot < 2; slot++)
    {
      if (enc->pool[slot] == addr)
        {
          enc->pool[slot] = NULL;
          enc->pool_size[slot] = 0;
          break;
        }
    }
}""",
    "free_buf by address")

open(P, "w").write(src)
print("applied %d edits" % len(edits))
for e in edits:
    print("  - " + e)

