"""Report bar samples as RGB with a delta, not as an equality test.

JPEG is lossy, so exact equality never holds and flagging every bar as
"differs" buries the signal it was meant to show.  What matters is how far off
each bar is: a couple of levels is compression, a swapped bar is off by a
hundred.
"""

import sys

P = ("/home/mi/vela_competition_ap_console_dev/contest/"
     "contest2026_264_VelaSightsuixingAIzhinengyanjing/app/jpeg_test/"
     "jpeg_test_main.c")

src = open(P).read()
edits = []


def sub(old, new, label):
    global src
    n = src.count(old)
    if n != 1:
        print("FAIL [%s]: found %d, expected 1" % (label, n))
        sys.exit(1)
    src = src.replace(old, new, 1)
    edits.append(label)


sub("""/****************************************************************************
 * Name: jpeg_test_verify""",
    """/****************************************************************************
 * Name: jpeg_test_unpack565
 *
 * Description:
 *   RGB565 back to 8-bit channels, so differences can be read in the units
 *   the source was written in.
 *
 ****************************************************************************/

static void jpeg_test_unpack565(uint16_t px, int *r, int *g, int *b)
{
  *r = (int)((px >> 11) & 0x1f) * 8;
  *g = (int)((px >> 5) & 0x3f) * 4;
  *b = (int)(px & 0x1f) * 8;
}

