  nxmutex_lock(&g_psram_lock);
  if ((unsigned int)pool < BK7258_PSRAM_POOL_COUNT &&
      g_state == BK7258_PSRAM_ONLINE &&
      range_contains(g_pool_region[pool].base, g_pool_region[pool].size,
                     ptr, 1))
    {
      mm_free(g_pool_heap[pool], ptr);
