#!/usr/bin/env python3
"""Rewrite the two allocator edits: one PSRAM allocator, no ambiguity.

Falling back from the encode pool to the general PSRAM heap would leave two
possible owners for a pointer and no exported predicate to tell them apart,
which is what the earlier hand-rolled tracking got wrong.  Allocating only
from the pool keeps the release path unambiguous, and a request too large for
it simply fails: REQBUFS then reports ENOMEM and the caller drops to one
buffer per queue, which is already how the largest frame size is handled.
"""

import re
import sys

SCRIPT = "/tmp/stage_b.py"
src = open(SCRIPT).read()

old_alloc = '''      addr = bk7258_media_pool_alloc(BK7258_JPEG_POOL, 32, size);

      if (addr == NULL)
        {
          /* The dedicated pool is the right home, but a frame too large for
           * it should still encode if the general heap can take it.
           */

          addr = bk7258_psram_memalign(32, size);
        }

      if (addr == NULL)
        {
          return NULL;
        }'''

new_alloc = '''      /* Only ever this pool, so free_buf has one answer.  A frame too big
       * for it fails here, REQBUFS reports ENOMEM, and the caller retries
       * with one buffer per queue.
       */

      addr = bk7258_media_pool_alloc(BK7258_JPEG_POOL, 32, size);

      if (addr == NULL)
        {
          return NULL;
        }'''

old_free = '''      /* media_pool_free() range-checks the pointer itself and reports EINVAL
       * for anything outside the pool, which is how a general-heap block is
       * told apart from a pooled one without tracking it.
       */

      int saved = get_errno();

      set_errno(0);
      bk7258_media_pool_free(BK7258_JPEG_POOL, addr);

      if (get_errno() != 0)
        {
          bk7258_psram_free(addr);
        }

      set_errno(saved);'''

new_free = '''      bk7258_media_pool_free(BK7258_JPEG_POOL, addr);'''

old_msg = '''  printf("bk7258_jpeg: %zu byte pool from %s\\\\n", size,
         !use_psram ? "main heap" :
         bk7258_psram_pool_contains(BK7258_JPEG_POOL, addr) ?
         "psram-encode" : "psram general");'''

new_msg = '''  printf("bk7258_jpeg: %zu byte pool from %s\\\\n",
         size, use_psram ? "psram-encode" : "main heap");'''

for old, new, label in ((old_alloc, new_alloc, "alloc"),
                        (old_free, new_free, "free"),
                        (old_msg, new_msg, "message")):
    if src.count(old) != 1:
        print("FAIL [%s]: found %d, expected 1" % (label, src.count(old)))
        sys.exit(1)
    src = src.replace(old, new, 1)

open(SCRIPT, "w").write(src)
print("stage_b.py updated: single PSRAM allocator")

