#!/usr/bin/env python3
"""Check the captured frame's byte order against the frame itself.

A camera frame has no reference to compare against, so correctness has to come
from a property of the data.  Natural images are equally smooth across every
pixel boundary, which means the mean |dY| between the two luma samples of a
pair must match the mean |dY| across a pair boundary.  Read the luma from the
wrong bytes and the two disagree by roughly a factor of two, because every
adjacent pair has been transposed.

This is the measurement bk7258_camera_imgsensor.c used to establish the layout
in the first place; running it here confirms the encoder was handed the frame
it thinks it was, using the real data rather than a synthetic stand-in.

Chroma cannot be checked this way -- exchanging Cb and Cr leaves the joint
distribution alone -- so that half rests on the synthetic test, where a
reference does exist.
"""

import sys

P = ("/home/mi/vela_competition_ap_console_dev/contest/"
     "contest2026_264_VelaSightsuixingAIzhinengyanjing/app/jpeg_test/"
     "jpeg_test_main.c")

src = open(P).read()
edits = []


def sub(old, new, label):
    global src
    n = src.count(old)
    if n != 1:
        print("FAIL [%s]: found %d, expected 1" % (label, n))
        sys.exit(1)
    src = src.replace(old, new, 1)
    edits.append(label)


sub("""/****************************************************************************
 * Name: jpeg_test_cam""",
    """/****************************************************************************
 * Name: jpeg_test_check_order
 *
 * Description:
 *   Confirm which byte of each pair holds which luma, from the frame itself.
 *
 *   Reported as two smoothness figures.  Whichever assignment makes the
 *   within-pair difference match the across-pair difference is the correct
 *   one; the wrong one roughly doubles the across-pair figure because it
 *   transposes every adjacent column.
 *
 ****************************************************************************/

static void jpeg_test_check_order(const uint8_t *frame, uint32_t w,
                                  uint32_t h)
{
  uint32_t rows = h > 64 ? 64 : h;
  uint32_t within[2] = {
    0, 0
  };

  uint32_t across[2] = {
    0, 0
  };

  uint32_t n = 0;
  uint32_t row;
  uint32_t col;
  int which;

  /* Two candidate luma placements: bytes 3 and 1 (the camera's, even column
   * last) against bytes 1 and 3 (textbook).
   */

  static const uint8_t y0[2] = {
    3, 1
  };

  static const uint8_t y1[2] = {
    1, 3
  };

  for (row = 0; row < rows; row++)
    {
      const uint8_t *p = frame + (size_t)row * w * 2;

      for (col = 0; col + 3 < w; col += 2)
        {
          for (which = 0; which < 2; which++)
            {
              int a = p[y0[which]];
              int b = p[y1[which]];
              int c = p[4 + y0[which]];
              int d;

              d = b - a;
              within[which] += (uint32_t)(d < 0 ? -d : d);

              d = c - b;
              across[which] += (uint32_t)(d < 0 ? -d : d);
            }

          n++;
          p += 4;
        }
    }

  if (n == 0)
    {
      return;
    }

  /* Scaled by 100 so the ratio survives integer division. */

  for (which = 0; which < 2; which++)
    {
      uint32_t wi = within[which] * 100 / n;
      uint32_t ac = across[which] * 100 / n;

      printf("jpeg_test: luma at %u/%u: within %lu.%02lu across %lu.%02lu%s\\n",
             y0[which], y1[which],
             (unsigned long)(wi / 100), (unsigned long)(wi % 100),
             (unsigned long)(ac / 100), (unsigned long)(ac % 100),
             which == 0 ? "   <- used" : "");
    }

  printf("jpeg_test: the assignment whose two figures agree is the right "
         "one\\n");
}

/****************************************************************************
 * Name: jpeg_test_cam""",
    "check_order")

