---

# 七、实战：录音 `AUDIOIOC_START` 之后发生了什么

<callout emoji="memo" background-color="light-blue" border-color="blue">
本节把 `audio_test rec` 那一行 `ioctl(fd, AUDIOIOC_START, 0)` 之后的完整调用链拆开，**每一层都给出真实代码**（不是伪代码），关键语句旁边有注释。所有行号对应实际文件，可以直接跳过去核对。
</callout>

## 全景：一次录音的九步

```mermaid
sequenceDiagram
    participant App as 应用 audio_test
    participant Up as 上半部 audio.c
    participant Dev as 板级 audio_dev.c
    participant Chip as 芯片层 aud.c
    participant HW as AUD 硬件

    App->>Up: ioctl(AUDIOIOC_START, 0)
    Up->>Up: 状态机校验 PREPARED?
    Up->>Dev: lower->ops->start(lower)
    Dev->>Chip: set_rx_callback(rx_callback)
    Dev->>Chip: adc_start()
    Chip->>HW: 置 ADC_ENABLE 位
    Dev->>Chip: rx_int_enable(true)
    Chip->>HW: 置 ADC_INT_EN 位
    Note over App,HW: ── 以上是同步调用，返回 ──
    HW->>Chip: FIFO 超过阈值 → 中断
    Chip->>Dev: g_aud_rx_cb(arg)
    Dev->>Chip: adc_read(samples, room)
    Chip-->>Dev: 从 FIFO 搬样本
    Dev->>Dev: 缓冲满 → doneq + HPWORK
    Dev->>Up: upper(AUDIO_CALLBACK_DEQUEUE)
    Up->>App: 消息队列 AUDIO_MSG_DEQUEUE
    App->>Up: 统计后重新 ENQUEUEBUFFER
```

---

## 第 1 步：应用层发起

`app/audio_test/audio_test_main.c:933` `audio_test_run()`

START **之前**必须先把空缓冲挂进队列，否则 ADC 一开就没地方放数据：

```c
if (capture)
  {
    for (i = 0; i < cap.nbuffers; i++)
      {
        cap.buffers[i]->nbytes = 0;          /* 录音方向：nbytes 是"已收多少"，
                                              * 入队前必须清零，否则驱动会以为
                                              * 缓冲里已有数据、从中间往后写 */
        audio_test_enqueue(&cap, cap.buffers[i]);
      }
  }

if (capture)
  {
    if (ioctl(cap.fd, AUDIOIOC_START, 0) < 0)   /* ← 本节的起点 */
      {
        printf("audio_test: capture START failed: %d\n", errno);
        ret = -errno;
        goto done;
      }

    cap.started = true;
  }
```

入队本身（`:540`）：

```c
static int audio_test_enqueue(struct audio_test_stream_s *stream,
                              struct ap_buffer_s *apb)
{
  struct audio_buf_desc_s desc;

  desc.numbytes = apb->nbytes;
  desc.u.buffer = apb;                  /* 传的是缓冲指针本身，不是拷贝 —— 上下层
                                         * 共享同一块内存，这是零拷贝的关键 */

  ret = ioctl(stream->fd, AUDIOIOC_ENQUEUEBUFFER, (unsigned long)&desc);
  if (ret < 0)
    {
      return -errno;
    }

  stream->inflight++;                   /* 记账：有几个缓冲在驱动手里 */
  return OK;
}
```

---

## 第 2 步：上半部做状态机校验

`nuttx/audio/audio.c:608` `audio_start()` —— **上游代码，我没改**

```c
static int audio_start(FAR struct file *filep)
{
  FAR struct audio_upperhalf_s *upper = inode->i_private;
  FAR struct audio_lowerhalf_s *lower = upper->dev;

  DEBUGASSERT(upper != NULL && lower->ops->start != NULL);
  /* ↑ start 不允许为 NULL。这就是为什么下半部可以不实现 read/write/allocbuffer，
   *   但必须实现 start —— 判据在上半部这一行，不是我猜的 */

  if (upper->status->state == AUDIO_STATE_OPEN)
    {
      return -EPERM;                    /* 还没 CONFIGURE 就 START，直接拒绝 */
    }
  else if (upper->status->state == AUDIO_STATE_PAUSED)
    {
      return audio_resume(filep);       /* 暂停中的 START 语义是"继续" */
    }

  if (upper->status->state == AUDIO_STATE_PREPARED ||
      upper->status->state == AUDIO_STATE_XRUN)
    {
      ret = lower->ops->start(lower);   /* ★ 跳进我的下半部 */

      if (ret != OK)
        {
          return ret;
        }

      audio_setstate(upper, AUDIO_STATE_RUNNING);  /* 只有下半部成功才改状态 */
    }

  priv->state = AUDIO_STATE_RUNNING;
  return OK;
}
```

<callout emoji="bulb" background-color="light-blue" border-color="blue">
**这里体现了分层的价值**：状态机（谁能 START、重复 START 怎么办、暂停中 START 等于 resume）全部由上游统一实现，**每个芯片的驱动都不用自己写一遍**。我的下半部只管"把硬件打开"。
</callout>

---

## 第 3 步：板级下半部打开录音硬件

`board/beken/boards/bk7258/bk7258-ap/src/bk7258_audio_dev.c:704`

```c
static int bk7258_audio_start(FAR struct audio_lowerhalf_s *dev)
{
  FAR struct bk7258_audio_s *priv = (FAR struct bk7258_audio_s *)dev;
  /* ↑ 关键技巧：struct bk7258_audio_s 的第一个成员就是 struct audio_lowerhalf_s，
   *   所以指针可以直接强转。这是 NuttX 驱动的惯用法，等价于"继承" */

  if (!priv->configured)
    {
      return -EPERM;                    /* 没 configure 过就 start，拒绝 */
    }

  if (priv->running)
    {
      return OK;                        /* 重复 start 是幂等的，不是错误 */
    }

  if (priv->playback)
    {
      /* ... 播放分支：先 DAC 出声、延时、再开功放、最后解除静音，防爆音 ... */
    }
#ifdef CONFIG_BK7258_AUDIO_CAPTURE
  else
    {
      /* 录音分支只有三行，但顺序不能换 */

      bk7258_aud_set_rx_callback(bk7258_audio_rx_callback, priv);
      /* ① 先登记回调。必须在开中断之前 —— 否则中断先到而回调还是 NULL，
       *    芯片层会把这个方向的中断屏蔽掉（见第 5 步 ISR 的兜底逻辑） */

      bk7258_aud_adc_start();
      /* ② 使能 ADC，硬件开始往 FIFO 填样本 */

      bk7258_aud_rx_int_enable(true);
      /* ③ 最后才开中断。此时回调已就位、FIFO 已在积累数据 */
    }
#endif

  priv->running = true;
  priv->paused = false;

  return OK;
}
```

到这里 `ioctl` 就返回了 —— **数据搬运一个字节都还没发生**，全靠中断驱动。

---

## 第 4 步：芯片层落到寄存器

`board/beken/chips/bk7258/bk7258_aud.c`

三个函数，每个都只做一件事：

```c
/* :1100  登记回调。进临界区是因为 ISR 会读这两个全局变量 */
void bk7258_aud_set_rx_callback(bk7258_aud_xfer_cb_t cb, void *arg)
{
  irqstate_t flags = enter_critical_section();

  g_aud_rx_cb = cb;
  g_aud_rx_arg = arg;

  leave_critical_section(flags);
}

/* :1076  使能 ADC —— 就是置一个位 */
void bk7258_aud_adc_start(void)
{
  modifyreg32(BK7258_AUD_CONFIG, 0, BK7258_AUD_ADC_ENABLE);
  /*                            ↑清哪些位  ↑置哪些位
   * modifyreg32(addr, clr, set) 是读改写：value &= ~clr; value |= set;
   * 用它而不是直接 putreg32，是为了不碰同一个寄存器里别人的位 */
}

/* :1213  开/关 ADC FIFO 中断 */
void bk7258_aud_rx_int_enable(bool enable)
{
  irqstate_t flags = enter_critical_section();

  if (enable)
    {
      modifyreg32(BK7258_AUD_FIFO_CONFIG, 0, BK7258_AUD_ADC_INT_EN);
    }
  else
    {
      modifyreg32(BK7258_AUD_FIFO_CONFIG, BK7258_AUD_ADC_INT_EN, 0);
    }

  leave_critical_section(flags);
}
```

FIFO 的触发阈值在 `configure` 阶段就设好了（`:1032`）：

```c
modifyreg32(BK7258_AUD_FIFO_CONFIG, BK7258_AUD_ADC_WR_THRED_MASK,
            AUD_ADC_WR_THRESHOLD << BK7258_AUD_ADC_WR_THRED_SHIFT);
/* FIFO 里攒够这么多样本才触发中断。太小 → 中断频繁、CPU 被打爆；
 * 太大 → 延迟高、FIFO 可能溢出丢数据 */
```

---

## 第 5 步：硬件中断进来

`bk7258_aud.c:531` —— DAC 和 ADC **共用一根中断线、共用一个状态寄存器**，所以要靠标志位分发：

```c
static int bk7258_aud_isr(int irq, void *context, void *arg)
{
  uint32_t status = getreg32(BK7258_AUD_FIFO_STATUS);   /* 一次读出所有标志 */

  if ((status & BK7258_AUD_DACL_INT_FLAG) != 0 && g_aud_tx_cb != NULL)
    {
      g_aud_tx_cb(g_aud_tx_arg);        /* 播放方向 */
    }

  if ((status & BK7258_AUD_ADC_INT_FLAG) != 0 && g_aud_rx_cb != NULL)
    {
      g_aud_rx_cb(g_aud_rx_arg);        /* ★ 录音方向 → bk7258_audio_rx_callback */
    }

  /* 兜底：标志置了但没人处理，就把这个方向的中断屏蔽掉。
   * 这个块很重要 —— 这个硬件的中断标志不是写 1 清零的，而是靠"把 FIFO 伺候到
