## 第 6 步：板级搬数据（仍在中断上下文）

`bk7258_audio_dev.c:331`

```c
static void bk7258_audio_rx_callback(void *arg)
{
  FAR struct bk7258_audio_s *priv = arg;
  FAR struct ap_buffer_s *apb;
  unsigned int budget = BK7258_AUDIO_ISR_BUDGET;
  /* ↑ 预算上限。中断里不能无限循环搬数据，否则高优先级线程（比如 CP 心跳）
   *   被饿死。我在 JPEG 驱动上真踩过这个坑：应用层一个无界轮询把心跳饿了
   *   6 秒，CP 直接 assert 把板子重启了 */

  while (budget > 0)
    {
      apb = (FAR struct ap_buffer_s *)dq_peek(&priv->pendq);
      /* peek 不出队 —— 缓冲没填满就还得继续用它，不能摘下来 */

      if (apb == NULL)
        {
          /* 没有缓冲可填。屏蔽中断而不是空转；FIFO 里的样本就丢了，
           * 这正是录音 overrun 的正确行为（丢新数据而不是卡住系统）*/

          bk7258_aud_rx_int_enable(false);
          return;                       /* 重新使能的责任在 enqueuebuffer() */
        }

      if (apb->nbytes + sizeof(int16_t) <= apb->nmaxbytes)
        {
          FAR int16_t *samples = (FAR int16_t *)(apb->samp + apb->nbytes);
          /*                                     ↑ 从"已收到的位置"往后写 */
          unsigned int room = (apb->nmaxbytes - apb->nbytes) /
                              sizeof(int16_t);
          unsigned int read;

          if (room > budget)
            {
              room = budget;            /* 不超预算 */
            }

          read = bk7258_aud_adc_read(samples, room);   /* ★ 真正取样本 */
          apb->nbytes += read * sizeof(int16_t);       /* 推进"已收"游标 */
          budget -= read;

          if (read < room)
            {
              /* 要的没给够 → FIFO 空了。等下次中断，不要空转 */
              return;
            }
        }
      else
        {
          /* 这个缓冲装满了：摘下来交给回流路径 */
          (void)dq_remfirst(&priv->pendq);
          bk7258_audio_finish(priv, apb);
        }
    }
}
```

