void *audio_test_ogg_encoder_create(unsigned int rate, unsigned int bitrate)
{
  struct audio_test_ogg_enc_s *h;
  int encsize;
  int n;

  if (rate == 0 || rate / 1000 * OGG_FRAME_MS == 0)
    {
      return NULL;
    }

  h = calloc(1, sizeof(*h));
  if (h == NULL)
    {
      return NULL;
    }

  h->rate = rate;
  h->bitrate = bitrate;
  h->frame = rate / 1000 * OGG_FRAME_MS;

  h->packets = bk7258_psram_malloc((size_t)OGG_MAX_PACKET *
                                   OGG_PACKETS_PER_PAGE);
  if (h->packets == NULL)
    {
      free(h);
      return NULL;
    }

  /* SRAM for the state when it fits: it is touched constantly while
   * encoding and PSRAM is mapped non-cacheable.  PSRAM is the fallback
   * rather than the default for that reason alone.
