int conv_load_audio(const char *path, void **audio, size_t *audio_len)
{
  struct stat st;
  uint8_t *buf;
  ssize_t got;
  int fd;

  if (audio == NULL || audio_len == NULL)
    {
      return -EINVAL;
    }

  *audio = NULL;
  *audio_len = 0;

  if (path == NULL)
    {
      return OK;
    }

  if (stat(path, &st) < 0)
    {
      printf("conv: cannot stat %s: %d\n", path, errno);
      return -errno;
    }

  if (st.st_size <= 0 || st.st_size > CONV_AUDIO_CAP)
    {
      printf("conv: %s is %ld bytes, which is outside 1..%d\n", path,
             (long)st.st_size, CONV_AUDIO_CAP);
      return -EFBIG;
    }

  /* PSRAM: a recording is tens of kilobytes and the SRAM heap has other
   * uses, while nothing on this path is latency-sensitive.
   */

  buf = bk7258_psram_malloc((size_t)st.st_size);
  if (buf == NULL)
    {
      return -ENOMEM;
    }

  fd = open(path, O_RDONLY);
  if (fd < 0)
    {
      bk7258_psram_free(buf);
      return -errno;
    }

  got = read(fd, buf, (size_t)st.st_size);
  close(fd);

  if (got != st.st_size)
    {
      bk7258_psram_free(buf);
      return -EIO;
    }

  *audio = buf;
  *audio_len = (size_t)got;
  return OK;
}

