// Stands in for the browser: connects to server.js as a dashboard, asks the
// board for history, then opens one row.
//
// The point is to exercise the path the page will use -- dashboard -> server
// -> board -> server -> dashboard -> HTTP for the audio -- without needing a
// browser open, so a failure points at one hop rather than at "the page does
// not work".

import { WebSocket } from "ws";

const HOST = process.argv[2] ?? "127.0.0.1";
const PORT = Number(process.argv[3] ?? 8080);
const ws = new WebSocket(`ws://${HOST}:${PORT}/ws`);

let deviceId = null;
let step = 0;

const timer = setTimeout(() => {
  console.log("TIMEOUT: no result within 25 s");
  process.exit(1);
}, 25000);

function send(obj) {
  console.log("-> " + JSON.stringify(obj));
  ws.send(JSON.stringify(obj));
}

ws.on("open", () => send({ type: "hello", role: "dashboard" }));

ws.on("message", async (data) => {
  const msg = JSON.parse(data.toString());

  if (msg.type === "device_list") {
    const online = msg.devices.filter((d) => d.online);
    console.log(`<- device_list: ${online.length} online ` +
                `[${online.map((d) => d.deviceId).join(", ")}]`);
    if (online.length > 0 && step === 0) {
      step = 1;
      deviceId = online[0].deviceId;
      // Same filter that worked from the shell, so a difference in the
      // answer is a difference in the transport and not in the query.
      send({ type: "query", deviceId, requestId: "q1",
             from: 20260810, to: 20260818, keyword: "爬山",
             minConfidence: 0 });
    }
    return;
  }

  if (msg.type === "query_result") {
    console.log(`<- query_result: matched=${msg.matched} ` +
                `returned=${msg.returned} truncated=${msg.truncated}`);
    for (const r of msg.records ?? []) {
      console.log(`     seq=${r.seq} ${r.date} ${r.cue} ${r.confidence} ` +
                  `${r.audioBytes}B  ${r.summary}`);
    }
    if ((msg.records ?? []).length > 0 && step === 1) {
      step = 2;
      const seq = msg.records[0].seq;
      send({ type: "fetch", deviceId, requestId: "f1", seq });
    } else {
      clearTimeout(timer);
      ws.close();
    }
    return;
  }

  if (msg.type === "record") {
    console.log(`<- record pushed: seq=${msg.seq} url=${msg.url} ` +
                `${msg.audioBytes}B`);
    return;
  }

  if (msg.type === "fetch_done") {
    console.log(`<- fetch_done: seq=${msg.seq} url=${msg.url ?? "-"} ` +
                `${msg.error ?? ""}`);
    if (msg.url) {
      const res = await fetch(`http://${HOST}:${PORT}${msg.url}`);
      const buf = Buffer.from(await res.arrayBuffer());
      console.log(`   GET ${msg.url} -> HTTP ${res.status}, ` +
                  `${buf.length} bytes, ` +
                  `starts with "${buf.subarray(0, 4).toString("latin1")}"`);
    }
    clearTimeout(timer);
    ws.close();
    return;
  }

  if (msg.type !== "hello_ack") console.log("<- " + JSON.stringify(msg));
});

ws.on("error", (e) => {
  console.log("ERROR " + e.message);
  process.exit(1);
});

