// MiMo issues two kinds of credential and they do not share an endpoint. Using
// the wrong one answers 401 Invalid API Key, which reads as a bad key and sends
// people looking in the wrong place -- so the host follows the prefix instead of
// being left to whoever fills the form.
const LLM_HOSTS = {
  "sk-": "api.xiaomimimo.com",
  "tp-": "token-plan-cn.xiaomimimo.com"
};

function hostForKey(key) {
  for (const [prefix, host] of Object.entries(LLM_HOSTS)) {
    if (key.startsWith(prefix)) return host;
  }
  return null;
}

