#!/usr/bin/env python3
"""Measure the page in a real browser: does anything need scrolling?

The claim being checked is "every control is reachable without scrolling", so
the test is not "does it look right" but two numbers and a list:

  - document height vs viewport height (the page itself must not scroll)
  - every button and input's bounding box against the viewport

Run against the live backend, which is the only place the page is served from.
"""
import asyncio
import sys

from playwright.async_api import async_playwright

URL = "https://127.0.0.1:8443/"
SIZES = [(1920, 1080), (1600, 900), (1440, 900)]


async def main():
    bad_total = 0

    async with async_playwright() as p:
        browser = await p.firefox.launch()
        for w, h in SIZES:
            ctx = await browser.new_context(viewport={"width": w,
                                                      "height": h},
                                            ignore_https_errors=True)
            page = await ctx.new_page()
            await page.goto(URL, wait_until="load")
            await page.wait_for_timeout(1200)

            doc_h = await page.evaluate("document.documentElement.scrollHeight")
            doc_w = await page.evaluate("document.documentElement.scrollWidth")
            print("=== %dx%d ===" % (w, h))
            print("   文档高 %d / 视口高 %d %s"
                  % (doc_h, h, "OK" if doc_h <= h + 1 else "需要下滑!"))
            print("   文档宽 %d / 视口宽 %d %s"
                  % (doc_w, w, "OK" if doc_w <= w + 1 else "需要右滑!"))
            if doc_h > h + 1 or doc_w > w + 1:
                bad_total += 1

            # Every control, and whether it is inside the viewport.  Elements in
            # a collapsed <details> are legitimately hidden, so they are counted
            # separately rather than failed.
            out = await page.evaluate("""() => {
              const res = {off: [], hidden: 0, total: 0};
              document.querySelectorAll(
                '#cards button, #cards input, #cards select, '
                + '#statusbar button, #consolepane button, '
                + '#consolepane input, #logpane button, #logpane input'
              ).forEach((el) => {
                res.total++;
                const r = el.getBoundingClientRect();
                if (r.width === 0 && r.height === 0) { res.hidden++; return; }
                if (r.bottom > window.innerHeight + 1
                    || r.right > window.innerWidth + 1
                    || r.top < -1) {
                  res.off.push((el.id || el.tagName) + ' bottom=' +
                               Math.round(r.bottom));
                }
              });
              return res;
            }""")
            print("   控件 %d 个，折叠隐藏 %d 个，超出视口 %d 个"
                  % (out["total"], out["hidden"], len(out["off"])))
            for o in out["off"][:8]:
                print("     超出: %s" % o)
            if out["off"]:
                bad_total += 1

            # Cards must not be clipped without a scrollbar of their own.
            clipped = await page.evaluate("""() => {
              const bad = [];
              document.querySelectorAll('#cards .card').forEach((c) => {
                const body = c.querySelector('.card-body');
                if (!body) { bad.push(c.id + ' 没有滚动容器'); return; }
                if (body.scrollHeight > body.clientHeight + 1
                    && getComputedStyle(body).overflowY === 'visible') {
                  bad.push(c.id + ' 内容溢出但不可滚动');
                }
              });
              return bad;
            }""")
            for c in clipped:
                print("     %s" % c)
            if clipped:
                bad_total += 1

            await page.screenshot(path="/home/mi/convwork/page-%dx%d.png"
                                       % (w, h))
            await ctx.close()

        await browser.close()

    print("\n%s" % ("PASS 全部尺寸都不需要滚动" if bad_total == 0
                    else "FAIL %d 处问题" % bad_total))
    return 1 if bad_total else 0


sys.exit(asyncio.run(main()))

