# Against every scrolling ancestor, not just the viewport.  Checking
# the viewport alone passed a layout where the cards container
# clipped a whole card: the buttons were inside the window and
# outside the box that was showing them, which is exactly the
# "reachable only by scrolling" case this is supposed to catch.
out = await page.evaluate("""() => {
  const res = {off: [], hidden: 0, total: 0};

  const clippers = (el) => {
    const out = [];
    for (let p = el.parentElement; p; p = p.parentElement) {
      const s = getComputedStyle(p);
      if (/(auto|scroll|hidden)/.test(s.overflowY)
          || /(auto|scroll|hidden)/.test(s.overflowX)) {
        out.push(p);
      }
    }
    return out;
  };

  document.querySelectorAll(
    '#cards button, #cards input, #cards select, '
    + '#statusbar button, #consolepane button, '
    + '#consolepane input, #logpane button, #logpane input'
  ).forEach((el) => {
    res.total++;
    const r = el.getBoundingClientRect();
    if (r.width === 0 && r.height === 0) { res.hidden++; return; }

    if (r.bottom > window.innerHeight + 1
        || r.right > window.innerWidth + 1
        || r.top < -1) {
      res.off.push((el.id || el.tagName) + ' 出视口 bottom='
                   + Math.round(r.bottom));
      return;
    }

    for (const c of clippers(el)) {
      const cr = c.getBoundingClientRect();
      if (r.bottom > cr.bottom + 1 || r.top < cr.top - 1
          || r.right > cr.right + 1) {
        res.off.push((el.id || el.tagName) + ' 被 '
                     + (c.id || c.className) + ' 截断 bottom='
                     + Math.round(r.bottom) + ' 容器底='
                     + Math.round(cr.bottom));
        return;
      }
    }
  });
  return res;
}""")

